"""viewer_update.py"""
import os,sys
SYMBOLS_DIR=os.path.join(os.path.dirname(os.path.abspath(__file__)),"..","symbols")
VIEWER_TEMPLATE='<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8"/>\n<title>{BASE}</title>\n<style>\nbody{{background:#42424f;color:#5fcf89;font-family:Arial,sans-serif;text-align:center;margin:0;padding:0;}}\n\n.sound-control{{position:fixed;top:10px;right:10px;z-index:3000;}}\n.sound-toast{{position:fixed;top:56px;right:10px;background:rgba(0,0,0,0.8);color:white;padding:6px 10px;border-radius:8px;opacity:0;transition:opacity 200ms;}}\n.sound-toast.show{{opacity:1;}}\n#soundBtn{{padding:8px 10px;border:none;border-radius:8px;background:#3b2d3f;color:#b8b8b8;cursor:pointer;font-size:14px;}}\n\n.viewer-wrap{{margin-top:12px;display:inline-block;position:relative;}}\n#gifEl{{max-width:500px;width:500px;height:auto;display:block;}}\n\n.replay-wrap{{position:absolute;bottom:-42px;left:0;display:none;}}\n.replay-btn{{\n  width:36px;height:36px;\n  border:1px solid #555;border-radius:8px;\n  background:#2e2e38;color:#b8b8b8;\n  cursor:pointer;font-size:18px;\n  display:flex;align-items:center;justify-content:center;\n  transition:background 0.15s,color 0.15s;\n  padding:0;\n}}\n.replay-btn:hover{{background:#3a3a50;}}\n\n.tap-area{{margin-top:8px;}}\n#tapHold{{\n  display:inline-block;padding:9px 26px;\n  border:2px solid #5fcf89;border-radius:10px;\n  background:#2e2e38;color:#5fcf89;\n  cursor:pointer;font-size:14px;user-select:none;\n  transition:background 0.1s,color 0.1s;\n}}\n#tapHold.held{{background:#5fcf89;color:#2e2e38;}}\n#tapHold.tapped{{background:#3a4840;color:#a0d8b0;border-color:#a0d8b0;}}\n#statusLine{{font-size:12px;color:#aaa;letter-spacing:1px;margin:4px 0 0;min-height:16px;}}\n\n/* ── GIF CONTROLS ── */\n.gif-controls{{\n  position:fixed;right:10px;top:50%;transform:translateY(-50%);\n  display:flex;flex-direction:row;align-items:flex-start;z-index:1000;\n}}\n.gif-col{{display:flex;flex-direction:column;align-items:stretch;width:56px;}}\n.gif-btn{{\n  width:56px;height:56px;border:none;border-radius:0;\n  background:#2e2e38;color:#888;\n  cursor:pointer;font-size:20px;font-weight:bold;\n  transition:background 0.15s,color 0.15s,box-shadow 0.15s;\n  display:flex;flex-direction:column;align-items:center;justify-content:center;\n}}\n.gif-btn:first-child{{border-radius:10px 10px 0 0;}}\n.gif-btn.last-btn{{border-radius:0 0 10px 10px;}}\n.gif-btn.panel-open{{background:#3a2d44;color:#bf95cb;}}\n.gif-btn.has-effect{{color:#f0c8ff;box-shadow:inset 0 0 0 2px #bf95cb;}}\n.gif-btn.active-i{{background:#bf95cb;color:#1a1a22;}}\n.gif-sub{{font-size:9px;color:inherit;opacity:0.7;margin-top:1px;}}\n.btn-sep{{width:56px;height:1px;background:#3a3a48;}}\n\n.gif-panel{{\n  position:absolute;right:62px;\n  background:#1e1e28;border:1px solid #555;border-radius:10px;\n  padding:10px 12px;width:220px;\n  display:none;text-align:left;z-index:2000;\n}}\n.gif-panel.open{{display:block;}}\n#gPanel{{top:0;}}\n#fPanel{{top:114px;}}\n\n.panel-close{{\n  position:absolute;top:6px;right:8px;\n  background:none;border:none;color:#888;\n  font-size:16px;cursor:pointer;line-height:1;padding:0;\n}}\n.panel-close:hover{{color:#fff;}}\n\n.swatch-row{{display:flex;gap:7px;margin-bottom:9px;align-items:center;flex-wrap:wrap;}}\n.swatch{{\n  width:26px;height:26px;border-radius:50%;\n  border:2px solid transparent;cursor:pointer;\n  transition:border 0.12s,transform 0.1s;font-size:11px;\n  display:flex;align-items:center;justify-content:center;\n}}\n.swatch:hover{{transform:scale(1.18);}}\n.swatch.selected{{border:2px solid white;}}\n\n.slider-label{{font-size:11px;color:#aaa;margin-bottom:3px;}}\n.slider-wrap{{display:flex;align-items:center;gap:7px;margin-bottom:9px;}}\n.slider-wrap input[type=range]{{flex:1;accent-color:#bf95cb;}}\n\n.pc-row{{display:flex;gap:7px;margin-top:2px;}}\n.pc-btn{{\n  flex:1;padding:5px 0;\n  border:1px solid #555;border-radius:7px;\n  background:#2e2e38;color:#aaa;\n  cursor:pointer;font-size:12px;\n  transition:background 0.15s,color 0.15s;\n}}\n.pc-btn.active{{background:#bf95cb;color:#1a1a22;border-color:#bf95cb;}}\n\n/* ── MANIFEST DRAWER (slides up from bottom) ── */\n#manifestSidebar{{\n  position:fixed;\n  left:0;right:0;bottom:0;\n  height:310px;\n  background:#1e1e28;\n  border-top:1px solid #3a3a48;\n  overflow-x:auto;\n  overflow-y:hidden;\n  transform:translateY(100%);\n  transition:transform 0.28s ease;\n  z-index:2000;\n  font-family:\'Courier New\',monospace;\n  display:flex;\n  flex-direction:row;\n  align-items:stretch;\n  gap:0;\n}}\n#manifestSidebar.open{{\n  transform:translateY(0);\n}}\n\n/* drawer overlays — no content push needed */\nbody.sidebar-open .viewer-wrap,\nbody.sidebar-open .tap-area,\nbody.sidebar-open h2{{\n  margin-bottom:0;\n}}\n\n#mSidebarHeader{{\n  padding:14px 14px 10px;\n  border-bottom:1px solid #3a3a48;\n}}\n#mSidebarNumber{{font-size:10px;color:#7a7a8a;letter-spacing:2px;}}\n#mSidebarTitle{{font-size:18px;color:#5fcf89;letter-spacing:3px;margin-top:2px;}}\n\n.ms-section{{padding:10px 14px;border-bottom:1px solid #2e2e3a;}}\n.ms-label{{font-size:9px;letter-spacing:2px;color:#7a7a8a;text-transform:uppercase;margin-bottom:6px;}}\n\n/* simple fields */\n.ms-fields{{display:grid;grid-template-columns:1fr 1fr;gap:5px 10px;}}\n.ms-field{{display:flex;flex-direction:column;gap:1px;}}\n.ms-key{{font-size:9px;color:#7a7a8a;letter-spacing:1px;text-transform:uppercase;}}\n.ms-val{{font-size:11px;color:#c8c8d8;}}\n\n/* element grid — 4 cols × 5 rows */\n#msElementGrid{{\n  display:grid;\n  grid-template-columns:repeat(4,1fr);\n  grid-template-rows:repeat(5,48px);\n  gap:3px;\n  width:240px;\n  flex-shrink:0;\n}}\n.ms-cell{{\n  background:#2a2a36;\n  border:1px solid #3a3a48;\n  border-radius:4px;\n  padding:4px 5px;\n  display:flex;flex-direction:column;\n  align-items:flex-start;justify-content:center;\n  gap:1px;\n  overflow:hidden;\n}}\n.ms-cell.empty{{background:transparent;border-color:#2a2a36;}}\n.ms-arrow{{font-size:10px;color:#bf95cb;line-height:1;}}\n.ms-shape{{font-size:9px;color:#7a7a8a;line-height:1;}}\n.ms-name{{font-size:9px;color:#c8c8d8;line-height:1.2;}}\n.ms-elem-name{{font-size:8px;color:#5a5a6a;line-height:1;margin-top:1px;letter-spacing:0.5px;}}\n\n/* ── MANIFEST TAB (sits on top edge of drawer) ── */\n#manifestToggle{{\n  position:fixed;\n  bottom:0;\n  left:15%;\n  transform:none;\n  width:64px;height:22px;\n  border:1px solid #3a3a48;\n  border-bottom:none;\n  border-radius:6px 6px 0 0;\n  background:#1e1e28;\n  color:#7a7a8a;\n  cursor:pointer;font-size:11px;letter-spacing:1px;\n  display:flex;align-items:center;justify-content:center;\n  z-index:3001;\n  transition:color 0.15s, bottom 0.28s ease;\n}}\n#manifestToggle:hover{{color:#bf95cb;}}\n#manifestToggle.active{{\n  color:#bf95cb;\n  bottom:310px;\n}}\n\n/* scrollbar */\n#manifestSidebar::-webkit-scrollbar{{width:4px;}}\n#manifestSidebar::-webkit-scrollbar-track{{background:#1e1e28;}}\n#manifestSidebar::-webkit-scrollbar-thumb{{background:#3a3a48;border-radius:2px;}}\n\n/* ── MANIFEST/METADATA TAB BUTTONS (floating over content) ── */\n#drawerTabBar{{\n  position:absolute;\n  top:7px;right:10px;\n  display:flex;gap:4px;\n  z-index:2010;\n  pointer-events:auto;\n}}\n.drawer-tab-btn{{\n  width:24px;height:24px;\n  border:1px solid #3a3a48;border-radius:5px;\n  background:#2a2a36;color:#5a5a6a;\n  cursor:pointer;font-size:13px;\n  display:flex;align-items:center;justify-content:center;\n  transition:background 0.15s,color 0.15s,border 0.15s;\n  padding:0;\n}}\n.drawer-tab-btn:hover{{color:#bf95cb;border-color:#bf95cb;}}\n.drawer-tab-btn.active{{background:#3a2d44;color:#bf95cb;border-color:#bf95cb;}}\n\n/* metadata tab content */\n#metaTabContent{{\n  display:none;\n  flex-direction:row;\n  align-items:stretch;\n  width:100%;\n  flex-shrink:0;\n}}\n#metaTabContent.visible{{display:flex;}}\n\n/* metadata columns */\n.meta-col{{\n  padding:14px 16px;\n  border-right:1px solid #3a3a48;\n  display:flex;flex-direction:column;gap:6px;\n  flex-shrink:0;overflow-y:auto;\n  min-width:180px;\n}}\n.meta-col:last-child{{border-right:none;}}\n.meta-label{{font-size:9px;letter-spacing:2px;color:#7a7a8a;text-transform:uppercase;margin-bottom:2px;}}\n.meta-val{{font-size:11px;color:#c8c8d8;line-height:1.4;}}\n.meta-field{{display:flex;flex-direction:column;gap:1px;margin-bottom:6px;}}\n\n/* hex5 grid in metadata tab — same style as element grid */\n#metaHex5Grid{{\n  display:grid;\n  grid-template-columns:repeat(4,1fr);\n  gap:3px;\n  width:240px;\n  flex-shrink:0;\n}}\n\n/* effects row */\n.meta-effects{{\n  display:flex;gap:6px;flex-wrap:wrap;margin-top:4px;\n}}\n.meta-effect-pill{{\n  font-size:10px;padding:2px 7px;\n  border:1px solid #3a3a48;border-radius:4px;\n  background:#2a2a36;color:#bf95cb;\n  font-family:\'Courier New\',monospace;\n}}\n\n/* not minted state */\n#metaNotMinted{{\n  display:none;\n  padding:30px 20px;\n  font-size:11px;color:#4a4a5a;\n  text-align:center;letter-spacing:1px;\n  align-items:center;justify-content:center;\n  width:100%;\n}}\n#metaNotMinted.visible{{display:flex;}}\n\n\n/* ── PRESET PANEL (slim, slides from left) ── */\n#presetPanel{{\n  position:fixed;\n  left:0;top:0;bottom:0;\n  width:180px;\n  background:#1a1a24;\n  border-right:1px solid #3a3a48;\n  transform:translateX(-100%);\n  transition:transform 0.28s ease;\n  z-index:2001;\n  font-family:\'Courier New\',monospace;\n  display:flex;flex-direction:column;\n  overflow:hidden;\n}}\n#presetPanel.open{{transform:translateX(0);}}\n\n#presetHeader{{\n  padding:10px 12px 8px;\n  border-bottom:1px solid #3a3a48;\n  font-size:9px;letter-spacing:2px;color:#7a7a8a;text-transform:uppercase;\n  display:flex;align-items:center;justify-content:space-between;\n}}\n#presetHeader span{{color:#bf95cb;}}\n\n#presetList{{\n  flex:1;overflow-y:auto;padding:6px 0;\n}}\n#presetList::-webkit-scrollbar{{width:3px;}}\n#presetList::-webkit-scrollbar-thumb{{background:#3a3a48;border-radius:2px;}}\n\n.preset-item{{\n  display:flex;align-items:center;gap:0;\n  border-bottom:1px solid #222230;\n}}\n.preset-load{{\n  flex:1;padding:8px 10px;\n  background:none;border:none;color:#c8c8d8;\n  font-family:\'Courier New\',monospace;font-size:11px;\n  text-align:left;cursor:pointer;\n  transition:background 0.1s,color 0.1s;\n  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\n}}\n.preset-load:hover{{background:#2a2a38;color:#bf95cb;}}\n.preset-load.active-preset{{color:#5fcf89;}}\n.preset-sub{{\n  font-size:9px;color:#5a5a6a;display:block;margin-top:1px;\n  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;\n}}\n.preset-del{{\n  padding:8px 8px;background:none;border:none;\n  color:#3a3a4a;cursor:pointer;font-size:12px;flex-shrink:0;\n  transition:color 0.1s;\n}}\n.preset-del:hover{{color:#cf6f6f;}}\n\n#presetSaveArea{{\n  padding:8px 10px;\n  border-top:1px solid #3a3a48;\n  display:flex;flex-direction:column;gap:5px;\n}}\n#presetNameInput{{\n  width:100%;background:#2a2a36;border:1px solid #3a3a48;\n  border-radius:5px;color:#c8c8d8;font-family:\'Courier New\',monospace;\n  font-size:11px;padding:5px 7px;outline:none;\n}}\n#presetNameInput:focus{{border-color:#bf95cb;}}\n#presetNameInput::placeholder{{color:#4a4a5a;}}\n#presetSaveBtn{{\n  width:100%;padding:5px 0;background:#2a2a38;\n  border:1px solid #3a3a48;border-radius:5px;\n  color:#bf95cb;font-family:\'Courier New\',monospace;font-size:11px;\n  cursor:pointer;transition:background 0.15s,border 0.15s;\n}}\n#presetSaveBtn:hover{{background:#3a2d44;border-color:#bf95cb;}}\n\n/* preset tab — top left, 1/10 from top */\n#presetToggle{{\n  position:fixed;\n  top:10%;\n  left:0;\n  width:22px;height:64px;\n  border:1px solid #3a3a48;\n  border-left:none;\n  border-radius:0 6px 6px 0;\n  background:#1a1a24;\n  color:#7a7a8a;\n  cursor:pointer;font-size:11px;letter-spacing:1px;\n  display:flex;align-items:center;justify-content:center;\n  writing-mode:vertical-rl;\n  z-index:3001;\n  transition:color 0.15s, left 0.28s ease;\n}}\n#presetToggle:hover{{color:#bf95cb;}}\n#presetToggle.active{{color:#bf95cb;left:180px;}}\n\n</style>\n</head>\n<body>\n\n<div class="sound-control">\n  <button id="soundBtn">&#127925;</button>\n</div>\n<div id="soundToast" class="sound-toast"></div>\n\n<!-- MANIFEST DRAWER (horizontal layout) -->\n<div id="manifestSidebar">\n\n  <!-- floating tab buttons -->\n  <div id="drawerTabBar">\n    <button class="drawer-tab-btn active" id="tabManifestBtn" title="Manifest">&#9776;</button>\n    <button class="drawer-tab-btn" id="tabMetaBtn" title="Metadata">&#11042;</button>\n  </div>\n\n  <!-- MANIFEST TAB CONTENT -->\n  <div id="manifestTabContent" style="display:flex;flex-direction:row;align-items:stretch;flex-shrink:0;">\n    <!-- col 1: number + title + info fields + notes -->\n    <div style="min-width:200px;max-width:240px;padding:14px 16px;border-right:1px solid #3a3a48;display:flex;flex-direction:column;gap:0;flex-shrink:0;overflow-y:auto;">\n      <div id="mSidebarNumber" style="font-size:10px;color:#7a7a8a;letter-spacing:2px;"></div>\n      <div id="mSidebarTitle" style="font-size:18px;color:#5fcf89;letter-spacing:3px;margin-top:2px;margin-bottom:10px;"></div>\n      <div style="font-size:9px;letter-spacing:2px;color:#7a7a8a;text-transform:uppercase;margin-bottom:6px;">info</div>\n      <div class="ms-fields" id="msFields"></div>\n      <div id="msNotesSection" style="display:none;margin-top:10px;">\n        <div style="font-size:9px;letter-spacing:2px;color:#7a7a8a;text-transform:uppercase;margin-bottom:4px;">notes</div>\n        <div id="msNotes" style="font-size:11px;color:#7a7a8a;line-height:1.6;font-style:italic;"></div>\n      </div>\n    </div>\n    <!-- col 2: element code -->\n    <div style="padding:14px 16px;flex-shrink:0;">\n      <div style="font-size:9px;letter-spacing:2px;color:#7a7a8a;text-transform:uppercase;margin-bottom:8px;">element code</div>\n      <div id="msElementGrid"></div>\n    </div>\n  </div>\n\n  <!-- METADATA TAB CONTENT -->\n  <div id="metaTabContent" style="flex-direction:column;">\n    <!-- not minted message -->\n    <div id="metaInnerRow" style="display:flex;flex-direction:row;align-items:stretch;flex:1;overflow-x:auto;">\n  <div id="metaNotMinted">not minted</div>\n    <!-- col 1: mint info + effects -->\n    <div class="meta-col" id="metaInfoCol" style="display:none;">\n      <div class="meta-field">\n        <div class="meta-label">generation</div>\n        <div class="meta-val" id="metaGeneration"></div>\n      </div>\n      <div class="meta-field">\n        <div class="meta-label">chain</div>\n        <div class="meta-val" id="metaChain"></div>\n      </div>\n      <div class="meta-field">\n        <div class="meta-label">mint date</div>\n        <div class="meta-val" id="metaMintDate"></div>\n      </div>\n      <div class="meta-field">\n        <div class="meta-label">effects</div>\n        <div class="meta-effects" id="metaEffects"></div>\n      </div>\n    </div>\n    <!-- col 2: hex5 grid -->\n    <div class="meta-col" id="metaGridCol" style="display:none;">\n      <div class="meta-label">element roll</div>\n      <div id="metaHex5Grid"></div>\n    </div>\n  </div><!-- end metaInnerRow -->\n\n  <!-- owned by footer — inside metaTabContent, only visible with metadata tab -->\n  <div id="metaOwnedRow" style="display:none;\n    position:fixed;\n    bottom:0;left:0;right:0;\n    border-top:1px solid #3a3a48;\n    padding:5px 12px;\n    background:#1a1a22;\n    z-index:2500;\n    flex-direction:row;align-items:center;gap:12px;">\n    <div style="font-size:9px;color:#7a7a8a;white-space:nowrap;flex:1;">owner&nbsp;<span id="metaOwnerAddr" style="font-size:10px;color:#4a9eff;font-family:\'Courier New\',monospace;"></span></div>\n    <div style="font-size:9px;color:#7a7a8a;white-space:nowrap;flex-shrink:0;">token&nbsp;<span id="metaTokenId" style="color:#c8c8d8;"></span></div>\n    <span id="metaSymbolNum" style="display:none;"></span>\n  </div>\n  </div><!-- end metaTabContent -->\n\n</div><!-- end manifestSidebar -->\n\n<!-- PRESET PANEL -->\n<div id="presetPanel">\n  <div id="presetHeader">\n    <span>Presets</span>\n    <span id="presetCount"></span>\n  </div>\n  <div id="presetList"></div>\n  <div id="presetSaveArea">\n    <input id="presetNameInput" type="text" placeholder="preset name..." maxlength="24"/>\n    <button id="presetSaveBtn">&#8679; Save current</button>\n  </div>\n</div>\n\n<!-- PRESET TAB -->\n<button id="presetToggle" title="Toggle presets">&#9776;</button>\n\n<h2 style="margin:10px 0 6px;transition:margin-left 0.25s ease;" id="pageTitle">{BASE}</h2>\n\n<div class="viewer-wrap">\n  <img id="gifEl" src="" alt=""/>\n  <div class="replay-wrap" id="replayWrap">\n    <button class="replay-btn" id="replayBtn" title="Replay">&#8635;</button>\n  </div>\n</div>\n\n<div class="tap-area">\n  <button id="tapHold">&#9675; Tap &#9675;</button>\n  <div id="statusLine">&#8212;</div>\n</div>\n\n<!-- MANIFEST TAB -->\n<button id="manifestToggle" title="Toggle manifest">&#9135; &#9135;</button>\n\n<!-- GIF CONTROLS -->\n<div class="gif-controls">\n  <div style="position:relative;">\n    <div class="gif-panel" id="gPanel">\n      <button class="panel-close" id="gClose">&#10005;</button>\n      <div class="slider-label">Color</div>\n      <div class="swatch-row" id="gSwatches">\n        <div class="swatch" data-color="red" style="background:red;"></div>\n        <div class="swatch" data-color="green" style="background:#00dd00;"></div>\n        <div class="swatch" data-color="blue" style="background:#4488ff;"></div>\n        <div class="swatch" data-color="white" style="background:white;"></div>\n        <div class="swatch" data-color="" style="background:#333;border:1px dashed #888;color:#888;">&#10005;</div>\n      </div>\n      <div class="slider-label">Size <span id="gSizeVal">10</span>px</div>\n      <div class="slider-wrap">\n        <input id="gSize" type="range" min="1" max="50" value="10" step="1"/>\n      </div>\n      <div class="pc-row">\n        <button class="pc-btn" id="gPulseBtn">Pulse</button>\n        <button class="pc-btn" id="gCycleBtn">Cycle</button>\n      </div>\n    </div>\n\n    <div class="gif-panel" id="fPanel">\n      <button class="panel-close" id="fClose">&#10005;</button>\n      <div class="slider-label">Color</div>\n      <div class="swatch-row" id="fSwatches">\n        <div class="swatch" data-color="cyan" style="background:cyan;"></div>\n        <div class="swatch" data-color="magenta" style="background:magenta;"></div>\n        <div class="swatch" data-color="yellow" style="background:yellow;"></div>\n        <div class="swatch" data-color="" style="background:#333;border:1px dashed #888;color:#888;">&#10005;</div>\n      </div>\n      <div class="slider-label">Opacity <span id="fOpVal">40</span></div>\n      <div class="slider-wrap">\n        <input id="fOpacity" type="range" min="25" max="50" value="40" step="1"/>\n      </div>\n      <div class="pc-row">\n        <button class="pc-btn" id="fPulseBtn">Pulse</button>\n        <button class="pc-btn" id="fCycleBtn">Cycle</button>\n      </div>\n    </div>\n\n    <div class="gif-col">\n      <button class="gif-btn" id="gBtn">\n        <div style="font-size:20px;font-weight:bold;">G</div>\n        <div class="gif-sub">glow</div>\n      </button>\n      <div class="btn-sep"></div>\n      <button class="gif-btn" id="iBtn">\n        <div style="font-size:20px;font-weight:bold;">I</div>\n        <div class="gif-sub">invert</div>\n      </button>\n      <div class="btn-sep"></div>\n      <button class="gif-btn last-btn" id="fBtn">\n        <div style="font-size:20px;font-weight:bold;">F</div>\n        <div class="gif-sub">filter</div>\n      </button>\n    </div>\n  </div>\n</div>\n\n<div style="height:50px;"></div>\n\n<script>\nwindow.addEventListener("DOMContentLoaded", function() {{\n\n  /* ── CONFIG ──────────────────────────────────────────────────────\n     BASE and PLAYS_ONCE can be overridden by URL parameters:\n       viewer.html?folder=0001 - inni\n       viewer.html?folder=0001 - inni&plays_once=true\n     If no URL params, falls back to the hardcoded defaults below.\n     ────────────────────────────────────────────────────────────── */\n  var DEFAULT_BASE       = "{BASE}";\n  var DEFAULT_PLAYS_ONCE = {PLAYS_ONCE};\n\n  var params     = new URLSearchParams(window.location.search);\n  var BASE       = params.get("folder") || DEFAULT_BASE;\n  var PLAYS_ONCE = params.get("plays_once") === "true" || DEFAULT_PLAYS_ONCE;\n\n  /* Effect URL params (set by mint page):\n     gcolor, gsize, gpulse, gcycle,\n     fcolor, fopacity, fpulse, fcycle,\n     negative, nft_gen, nft_chain, nft_ts, nft_effects, nft_grid */\n  var urlGColor   = params.get("gcolor")   || "";\n  var urlGSize    = parseInt(params.get("gsize") || "10");\n  var urlGPulse   = params.get("gpulse")   === "true";\n  var urlGCycle   = params.get("gcycle")   === "true";\n  var urlFColor   = params.get("fcolor")   || "";\n  var urlFOpacity = parseInt(params.get("fopacity") || "40");\n  var urlFPulse   = params.get("fpulse")   === "true";\n  var urlFCycle   = params.get("fcycle")   === "true";\n  var urlNeg      = params.get("negative") === "true";\n  var urlHasEffects = urlGColor || urlGPulse || urlGCycle || urlFColor || urlFPulse || urlFCycle || urlNeg;\n\n  /* NFT metadata URL params */\n  var nftGen      = params.get("nft_gen")      || "";\n  var nftChain    = params.get("nft_chain")    || "";\n  var nftTs       = params.get("nft_ts")       || "";\n  var nftEffects  = params.get("nft_effects")  || "";\n  var nftGrid     = params.get("nft_grid")     || "";\n  var nftOwner    = params.get("nft_owner")    || "";\n  var nftTokenId  = params.get("nft_tokenid")  || "";\n  var nftNumber   = params.get("nft_number")   || "";\n  var hasMeta     = !!(nftGen || nftChain || nftTs);\n  /* ────────────────────────────────────────────────────────────── */\n\n  var gifEl = document.getElementById("gifEl");\n  gifEl.src = BASE + ".gif";\n  document.getElementById("pageTitle").textContent = BASE;\n  document.title = BASE;\n\n  /* Apply URL effect params on load */\n  function applyUrlEffects() {{\n    if (!urlHasEffects) return;\n    gColor   = urlGColor;\n    gSize    = isNaN(urlGSize) ? 10 : urlGSize;\n    fColor   = urlFColor;\n    fOpacity = isNaN(urlFOpacity) ? 40 : urlFOpacity;\n    negative = urlNeg;\n    document.getElementById("gSize").value    = gSize;\n    document.getElementById("fOpacity").value = fOpacity;\n    document.getElementById("gSizeVal").textContent = gSize;\n    document.getElementById("fOpVal").textContent   = fOpacity;\n    document.getElementById("iBtn").classList.toggle("active-i", negative);\n    // trigger pulse/cycle after swatches init\n    setTimeout(function() {{\n      updateSwatches("g"); updateSwatches("f");\n      if (urlGPulse) document.getElementById("gPulseBtn").click();\n      if (urlGCycle) document.getElementById("gCycleBtn").click();\n      if (urlFPulse) document.getElementById("fPulseBtn").click();\n      if (urlFCycle) document.getElementById("fCycleBtn").click();\n      updateAll();\n    }}, 50);\n  }}\n\n  if (PLAYS_ONCE) {{\n    document.getElementById("replayWrap").style.display = "block";\n  }}\n\n  document.getElementById("replayBtn").onclick = function() {{\n    gifEl.src = BASE + ".gif?" + Date.now();\n  }};\n\n  /* ── MANIFEST SIDEBAR ── */\n  function parseFrames(raw) {{\n    if (!raw) return raw;\n    var m = raw.match(/^(\\d+)\\(([^)]+)\\)$/);\n    if (!m) return raw;\n    var count    = m[1];\n    var delayNum = parseFloat(m[2].replace(",", "."));\n    if (isNaN(delayNum)) return raw;\n    var sec = delayNum < 1 ? delayNum : delayNum / 10;\n    return count + " frames  ·  " + sec.toFixed(1) + "s";\n  }}\n\n  function populateManifest(manifest) {{\n    document.getElementById("mSidebarNumber").textContent = manifest.number || "";\n    document.getElementById("mSidebarTitle").textContent  = manifest.title  || "";\n\n    var fields = [\n      {{ key: "date",      val: manifest.date }},\n      {{ key: "size",      val: manifest.size }},\n      {{ key: "dimension", val: manifest.dimension }},\n      {{ key: "filetype",  val: manifest.filetype }},\n      {{ key: "frames",    val: parseFrames(manifest.frames) }},\n      {{ key: "timeline",  val: manifest.timeline }},\n    ];\n    var fg = document.getElementById("msFields");\n    fg.innerHTML = "";\n    fields.forEach(function(f) {{\n      if (!f.val) return;\n      var div = document.createElement("div");\n      div.className = "ms-field";\n      div.innerHTML = \'<div class="ms-key">\' + f.key + \'</div>\' +\n                      \'<div class="ms-val">\' + f.val + \'</div>\';\n      fg.appendChild(div);\n    }});\n\n    var ec   = manifest.element_code;\n    var grid = document.getElementById("msElementGrid");\n    grid.innerHTML = "";\n    if (ec) {{\n      Object.keys(ec).sort().forEach(function(lk) {{\n        ec[lk].forEach(function(cell) {{\n          var div = document.createElement("div");\n          if (!cell || cell === "---") {{\n            div.className = "ms-cell empty";\n          }} else {{\n            var mparts = cell.trim().split(/\\s+/);\n            var marrow = mparts[0] || "";\n            var mshape = mparts[1] || "";\n            var mname  = mparts.slice(2).join(" ");\n            div = makeElemCell(marrow, mshape, mname);\n          }}\n          grid.appendChild(div);\n        }});\n      }});\n    }}\n\n    if (manifest.info && manifest.info !== "-") {{\n      document.getElementById("msNotes").textContent = manifest.info;\n      document.getElementById("msNotesSection").style.display = "block";\n    }}\n  }}\n\n  function populateOwnedRow() {{\n    if (!nftOwner && !nftTokenId) return;\n    var row = document.getElementById("metaOwnedRow");\n    row.style.display = "flex";\n    /* truncate address */\n    var addr = nftOwner ? nftOwner.slice(0,6) + "..." + nftOwner.slice(-4) : "";\n    document.getElementById("metaOwnerAddr").textContent = addr;\n    document.getElementById("metaOwnerAddr").title       = nftOwner;\n    document.getElementById("metaTokenId").textContent    = nftTokenId  || "—";\n    document.getElementById("metaSymbolNum").textContent  = nftNumber   || "—";\n  }}\n\n  // Fetch manifest — works both standalone and via server\n  fetch("manifest.json")\n    .then(function(r) {{ return r.json(); }})\n    .then(function(m) {{ populateManifest(m); }})\n    .catch(function() {{}});\n\n  /* ── ELEMENT SYMBOL MAP ── */\n  /* Element symbol → Norwegian name map (correct unicode codepoints) */\n  var ELEM_SYM_MAP = {{\n    "⌃": "luft",   /* ⌃ */\n    "△": "ild",    /* △ */\n    "▽": "vann",   /* ▽ */\n    "▢": "jord",   /* ▢ */\n    "✳": "plante", /* ✳ */\n    "ϟ": "lyn",    /* ϟ */\n    "⌂": "metall", /* ⌂ */\n    "·": "tom"     /* · */\n  }};\n\n  /* Norwegian element names (manifest uses these directly as the \'name\' part) */\n  var ELEM_NAMES = ["ild","luft","vann","jord","plante","lyn","metall","tom"];\n\n  function makeElemCell(arrow, shape, sym) {{\n    /* sym is either:\n       - a unicode symbol like ⌃ (from chain grid) → look up name\n       - a Norwegian word like luft (from manifest) → use as name, show symbol too  */\n    var div = document.createElement("div");\n    div.className = "ms-cell";\n    var displaySym  = sym;\n    var displayName = "";\n    if (ELEM_SYM_MAP[sym]) {{\n      /* chain format: sym is unicode symbol */\n      displayName = ELEM_SYM_MAP[sym];\n    }} else if (ELEM_NAMES.indexOf(sym) >= 0) {{\n      /* manifest format: sym is already the name, find the symbol */\n      displayName = sym;\n      var revMap = {{"luft":"⌃","ild":"△","vann":"▽","jord":"▢",\n                    "plante":"✳","lyn":"ϟ","metall":"⌂","tom":"·"}};\n      displaySym = revMap[sym] || sym;\n    }} else {{\n      displayName = sym;\n    }}\n    div.innerHTML =\n      \'<span class="ms-arrow">\' + arrow + \'</span>\' +\n      \'<span class="ms-shape">\' + shape + \'</span>\' +\n      \'<span class="ms-name">\'  + displaySym + \'</span>\' +\n      \'<span class="ms-elem-name">\' + displayName + \'</span>\';\n    return div;\n  }}\n\n  /* ── METADATA TAB ── */\n  function populateMetadata() {{\n    if (!hasMeta) {{\n      document.getElementById("metaNotMinted").classList.add("visible");\n      return;\n    }}\n    document.getElementById("metaNotMinted").classList.remove("visible");\n    document.getElementById("metaInfoCol").style.display = "flex";\n    document.getElementById("metaGridCol").style.display = "flex";\n\n    document.getElementById("metaGeneration").textContent = nftGen  || "—";\n    document.getElementById("metaChain").textContent      = nftChain || "—";\n\n    // format timestamp\n    if (nftTs && !isNaN(parseInt(nftTs))) {{\n      var d = new Date(parseInt(nftTs) * 1000);\n      var pad = function(n){{ return n < 10 ? "0"+n : n; }};\n      document.getElementById("metaMintDate").textContent =\n        pad(d.getDate()) + "/" + pad(d.getMonth()+1) + "-" +\n        String(d.getFullYear()).slice(2) + " " +\n        pad(d.getHours()) + ":" + pad(d.getMinutes());\n    }} else {{\n      document.getElementById("metaMintDate").textContent = nftTs || "—";\n    }}\n\n    // effect pills\n    var efContainer = document.getElementById("metaEffects");\n    efContainer.innerHTML = "";\n    if (nftEffects) {{\n      nftEffects.split(",").forEach(function(pill) {{\n        if (!pill.trim()) return;\n        var span = document.createElement("span");\n        span.className = "meta-effect-pill";\n        span.textContent = pill.trim();\n        efContainer.appendChild(span);\n      }});\n    }} else {{\n      efContainer.innerHTML = \'<span class="meta-effect-pill" style="border-color:#3a3a48;color:#4a4a5a;">none</span>\';\n    }}\n\n    // hex5 grid — rows separated by | cells by space\n    var hexGrid = document.getElementById("metaHex5Grid");\n    hexGrid.innerHTML = "";\n    if (nftGrid) {{\n      var rows = nftGrid.split("|");\n      /* Always render exactly 5 rows × 4 cols */\n      for (var ri = 0; ri < 5; ri++) {{\n        var rowStr = rows[ri] ? rows[ri].trim() : "";\n        var cells  = rowStr ? rowStr.split(" ") : [];\n        for (var ci = 0; ci < 4; ci++) {{\n          var cell = cells[ci] || "";\n          var div  = document.createElement("div");\n          if (!cell || cell === "---") {{\n            div.className = "ms-cell empty";\n          }} else {{\n            var arrow = cell.slice(0,1);\n            var shape = cell.slice(1,2);\n            var sym   = cell.slice(2);\n            div = makeElemCell(arrow, shape, sym);\n          }}\n          hexGrid.appendChild(div);\n        }}\n      }}\n    }}\n  }}\n  populateMetadata();\n  populateOwnedRow();\n\n  /* ── TAB TOGGLE ── */\n  var activeDrawerTab = "manifest";\n  document.getElementById("tabManifestBtn").onclick = function() {{\n    activeDrawerTab = "manifest";\n    document.getElementById("manifestTabContent").style.display = "flex";\n    document.getElementById("metaTabContent").classList.remove("visible");\n    document.getElementById("tabManifestBtn").classList.add("active");\n    document.getElementById("tabMetaBtn").classList.remove("active");\n  }};\n  document.getElementById("tabMetaBtn").onclick = function() {{\n    activeDrawerTab = "meta";\n    document.getElementById("manifestTabContent").style.display = "none";\n    document.getElementById("metaTabContent").classList.add("visible");\n    document.getElementById("tabMetaBtn").classList.add("active");\n    document.getElementById("tabManifestBtn").classList.remove("active");\n  }};\n\n  /* ── MANIFEST TOGGLE ── */\n  var sidebarOpen = false;\n  var toggleBtn   = document.getElementById("manifestToggle");\n  var sidebar     = document.getElementById("manifestSidebar");\n\n  function setManifestOpen(on) {{\n    sidebarOpen = on;\n    sidebar.classList.toggle("open", sidebarOpen);\n    toggleBtn.classList.toggle("active", sidebarOpen);\n    document.body.classList.toggle("sidebar-open", sidebarOpen);\n  }}\n\n  toggleBtn.onclick = function() {{\n    setManifestOpen(!sidebarOpen);\n    if(sidebarOpen && typeof presetOpen !== "undefined" && presetOpen) {{\n      setPresetOpen(false);\n    }}\n  }};\n\n  /* ── AUDIO ── */\n  var sbtn  = document.getElementById("soundBtn");\n  var toast = document.getElementById("soundToast");\n  var audio = new Audio(BASE + ".mp3");\n  audio.loop    = true;\n  audio.preload = "auto";\n\n  function showToast(t) {{\n    toast.textContent = t;\n    toast.classList.add("show");\n    setTimeout(function(){{ toast.classList.remove("show"); }}, 1500);\n  }}\n  audio.onerror = function() {{ showToast("No audio file"); }};\n  sbtn.onclick = async function() {{\n    if (audio.paused) {{\n      try {{ await audio.play(); sbtn.innerHTML = "&#9208;&#65039;"; }}\n      catch(e) {{ showToast("Playback blocked"); }}\n    }} else {{\n      audio.pause();\n      sbtn.innerHTML = "&#127925;";\n    }}\n  }};\n\n  /* ── EFFECTS STATE ── */\n  var tapped = false, negative = false;\n  var gColor = "", gSize = 10, fColor = "", fOpacity = 40;\n  var gPulseInterval = null, fPulseInterval = null;\n  var gCycleInterval = null, fCycleInterval = null;\n  var gHue = 0;\n  var fCycleHues     = [180, 300, 60];\n  var fCycleFrom     = 180, fCycleTo = 300, fCycleProgress = 0, fCycleSegment = 0;\n\n  /* ── TAP / RE-TAP ── */\n  var tapBtn = document.getElementById("tapHold");\n\n  tapBtn.addEventListener("mousedown", function() {{\n    tapped = true;\n    tapBtn.classList.add("held");\n    tapBtn.textContent = "● Tapped ●";\n    updateAll();\n  }});\n  tapBtn.addEventListener("touchstart", function(e) {{\n    e.preventDefault();\n    tapped = true;\n    tapBtn.classList.add("held");\n    tapBtn.textContent = "● Tapped ●";\n    updateAll();\n  }});\n\n  function doRetap() {{\n    tapBtn.classList.remove("held", "tapped");\n    tapped = false; negative = false;\n    gColor = ""; fColor = ""; gSize = 10; fOpacity = 40;\n    document.getElementById("gSize").value    = 10;\n    document.getElementById("fOpacity").value = 40;\n    document.getElementById("gSizeVal").textContent = 10;\n    document.getElementById("fOpVal").textContent   = 40;\n    stopAll();\n    updateSwatches("g"); updateSwatches("f");\n    document.getElementById("iBtn").classList.remove("active-i");\n    document.getElementById("gBtn").classList.remove("has-effect", "panel-open");\n    document.getElementById("fBtn").classList.remove("has-effect", "panel-open");\n    document.getElementById("gPanel").classList.remove("open");\n    document.getElementById("fPanel").classList.remove("open");\n    tapBtn.innerHTML = "&#9675; Tap &#9675;";\n    updateAll();\n  }}\n  tapBtn.addEventListener("mouseup",    function() {{ if(tapped) doRetap(); }});\n  tapBtn.addEventListener("mouseleave", function() {{\n    if(tapBtn.classList.contains("held")) {{\n      tapBtn.classList.remove("held");\n      tapBtn.classList.add("tapped");\n    }}\n  }});\n  tapBtn.addEventListener("touchend", function() {{ if(tapped) doRetap(); }});\n\n  /* ── PANELS ── */\n  function openPanel(which) {{\n    var panel  = document.getElementById(which + "Panel");\n    var btn    = document.getElementById(which + "Btn");\n    var other  = which === "g" ? "f" : "g";\n    var isOpen = panel.classList.contains("open");\n    panel.classList.toggle("open", !isOpen);\n    btn.classList.toggle("panel-open", !isOpen);\n    document.getElementById(other + "Panel").classList.remove("open");\n    document.getElementById(other + "Btn").classList.remove("panel-open");\n  }}\n  document.getElementById("gBtn").onclick = function() {{ openPanel("g"); }};\n  document.getElementById("fBtn").onclick = function() {{ openPanel("f"); }};\n  document.getElementById("gClose").onclick = function(e) {{\n    e.stopPropagation();\n    document.getElementById("gPanel").classList.remove("open");\n    document.getElementById("gBtn").classList.remove("panel-open");\n  }};\n  document.getElementById("fClose").onclick = function(e) {{\n    e.stopPropagation();\n    document.getElementById("fPanel").classList.remove("open");\n    document.getElementById("fBtn").classList.remove("panel-open");\n  }};\n  document.getElementById("iBtn").onclick = function() {{\n    negative = !negative;\n    document.getElementById("iBtn").classList.toggle("active-i", negative);\n    updateAll();\n  }};\n\n  /* ── SWATCHES ── */\n  function setupSwatches(p) {{\n    document.querySelectorAll("#" + p + "Swatches .swatch").forEach(function(s) {{\n      s.onclick = function() {{\n        if(p === "g") {{ gColor = s.dataset.color; stopCycle("g"); }}\n        else          {{ fColor = s.dataset.color; stopCycle("f"); }}\n        updateSwatches(p); updateAll();\n      }};\n    }});\n  }}\n  setupSwatches("g"); setupSwatches("f");\n\n  function updateSwatches(p) {{\n    var col = p === "g" ? gColor : fColor;\n    document.querySelectorAll("#" + p + "Swatches .swatch").forEach(function(s) {{\n      s.classList.toggle("selected", s.dataset.color === col);\n    }});\n    document.getElementById(p + "Btn").classList.toggle("has-effect", col !== "");\n  }}\n\n  /* ── SLIDERS ── */\n  document.getElementById("gSize").oninput = function() {{\n    gSize = parseInt(this.value);\n    document.getElementById("gSizeVal").textContent = gSize;\n    updateAll();\n  }};\n  document.getElementById("fOpacity").oninput = function() {{\n    fOpacity = parseInt(this.value);\n    document.getElementById("fOpVal").textContent = fOpacity;\n    updateAll();\n  }};\n\n  /* ── PULSE ── */\n  document.getElementById("gPulseBtn").onclick = function() {{\n    if(gPulseInterval) {{ clearInterval(gPulseInterval); gPulseInterval = null; document.getElementById("gPulseBtn").classList.remove("active"); return; }}\n    document.getElementById("gPulseBtn").classList.add("active");\n    var grow = true;\n    gPulseInterval = setInterval(function() {{\n      gSize += grow ? 1 : -1;\n      if(gSize >= 40) grow = false;\n      if(gSize <= 3)  grow = true;\n      document.getElementById("gSize").value = gSize;\n      document.getElementById("gSizeVal").textContent = gSize;\n      updateAll();\n    }}, 60);\n  }};\n  document.getElementById("fPulseBtn").onclick = function() {{\n    if(fPulseInterval) {{ clearInterval(fPulseInterval); fPulseInterval = null; document.getElementById("fPulseBtn").classList.remove("active"); return; }}\n    document.getElementById("fPulseBtn").classList.add("active");\n    var grow = true;\n    fPulseInterval = setInterval(function() {{\n      fOpacity += grow ? 1 : -1;\n      if(fOpacity >= 50) grow = false;\n      if(fOpacity <= 25) grow = true;\n      document.getElementById("fOpacity").value = fOpacity;\n      document.getElementById("fOpVal").textContent = fOpacity;\n      updateAll();\n    }}, 60);\n  }};\n\n  /* ── CYCLE ── */\n  document.getElementById("gCycleBtn").onclick = function() {{\n    if(gCycleInterval) {{ stopCycle("g"); return; }}\n    document.getElementById("gCycleBtn").classList.add("active");\n    if(!gColor) {{ gColor = "hsl(" + gHue + ",100%,55%)"; document.getElementById("gBtn").classList.add("has-effect"); }}\n    gCycleInterval = setInterval(function() {{\n      gHue  = (gHue + 3) % 360;\n      gColor = "hsl(" + gHue + ",100%,55%)";\n      updateAll();\n    }}, 40);\n  }};\n  document.getElementById("fCycleBtn").onclick = function() {{\n    if(fCycleInterval) {{ stopCycle("f"); return; }}\n    document.getElementById("fCycleBtn").classList.add("active");\n    fCycleSegment = 0; fCycleProgress = 0;\n    fCycleFrom = fCycleHues[0]; fCycleTo = fCycleHues[1];\n    if(!fColor) {{ fColor = "hsl(" + fCycleFrom + ",100%,50%)"; document.getElementById("fBtn").classList.add("has-effect"); }}\n    fCycleInterval = setInterval(function() {{\n      fCycleProgress += 0.025;\n      if(fCycleProgress >= 1) {{\n        fCycleProgress = 0;\n        fCycleSegment  = (fCycleSegment + 1) % fCycleHues.length;\n        fCycleFrom     = fCycleHues[fCycleSegment];\n        fCycleTo       = fCycleHues[(fCycleSegment + 1) % fCycleHues.length];\n      }}\n      var diff = ((fCycleTo - fCycleFrom + 540) % 360) - 180;\n      var h    = ((fCycleFrom + diff * fCycleProgress) + 360) % 360;\n      fColor   = "hsl(" + Math.round(h) + ",100%,50%)";\n      updateAll();\n    }}, 40);\n  }};\n\n  function stopCycle(p) {{\n    if(p === "g") {{ clearInterval(gCycleInterval); gCycleInterval = null; document.getElementById("gCycleBtn").classList.remove("active"); }}\n    else          {{ clearInterval(fCycleInterval); fCycleInterval = null; document.getElementById("fCycleBtn").classList.remove("active"); }}\n  }}\n  function stopAll() {{\n    clearInterval(gPulseInterval); gPulseInterval = null;\n    clearInterval(fPulseInterval); fPulseInterval = null;\n    stopCycle("g"); stopCycle("f");\n    document.getElementById("gPulseBtn").classList.remove("active");\n    document.getElementById("fPulseBtn").classList.remove("active");\n  }}\n\n  /* ── RENDER ── */\n  function updateAll() {{\n    if(tapped) {{\n      gifEl.style.filter = negative\n        ? "grayscale(1) invert(1) brightness(0.7)"\n        : "grayscale(1) brightness(0.7)";\n      updateStatus(); return;\n    }}\n    var f = "";\n    if(fColor) {{ var v = (fOpacity / 50).toFixed(2); f += "opacity(" + v + ") drop-shadow(0 0 0 " + fColor + ") "; }}\n    if(gColor) {{ f += "drop-shadow(0 0 " + gSize + "px " + gColor + ") "; }}\n    if(negative) f += "invert(1)";\n    gifEl.style.filter = f.trim();\n    updateStatus();\n  }}\n\n  function colorLabel(col) {{\n    if(!col) return "";\n    var map = {{"red":"R","green":"G","blue":"B","white":"W","cyan":"C","magenta":"M","yellow":"Y"}};\n    if(map[col]) return map[col];\n    var m = col.match(/hsl\\((\\d+)/);\n    if(m) return "~" + m[1] + "deg";\n    return col.slice(0,2).toUpperCase();\n  }}\n\n  function updateStatus() {{\n    var parts = [];\n\n    if(gColor || gCycleInterval || gPulseInterval) {{\n      var gBoth  = gCycleInterval && gPulseInterval;\n      var gCycle = gCycleInterval && !gPulseInterval;\n      var gPulse = gPulseInterval && !gCycleInterval;\n      if(gBoth)       parts.push("@G");\n      else if(gCycle) parts.push("\\u203BG[" + gSize + "]");\n      else if(gPulse) parts.push("*G:" + colorLabel(gColor));\n      else            parts.push("G:" + colorLabel(gColor) + "[" + gSize + "]");\n    }}\n\n    if(negative) parts.push("I");\n\n    if(fColor || fCycleInterval || fPulseInterval) {{\n      var fBoth  = fCycleInterval && fPulseInterval;\n      var fCycle = fCycleInterval && !fPulseInterval;\n      var fPulse = fPulseInterval && !fCycleInterval;\n      if(fBoth)       parts.push("@F");\n      else if(fCycle) parts.push("\\u203BF[" + fOpacity + "]");\n      else if(fPulse) parts.push("*F:" + colorLabel(fColor));\n      else            parts.push("F:" + colorLabel(fColor) + "[" + fOpacity + "]");\n    }}\n\n    if(tapped) parts.push("(tap)");\n    document.getElementById("statusLine").textContent = parts.length ? parts.join("  ") : "\\u2014";\n  }}\n\n\n  /* ── PRESETS ── */\n  var PRESETS_KEY = "viewerPresets";\n  var presets = JSON.parse(localStorage.getItem(PRESETS_KEY) || "[]");\n\n  function getState() {{\n    return {{\n      gColor:        gColor,\n      gSize:         gSize,\n      fColor:        fColor,\n      fOpacity:      fOpacity,\n      negative:      negative,\n      gPulse:        !!gPulseInterval,\n      fPulse:        !!fPulseInterval,\n      gCycle:        !!gCycleInterval,\n      fCycle:        !!fCycleInterval,\n    }};\n  }}\n\n  function stateLabel(st) {{\n    var parts = [];\n    if(st.gColor || st.gCycle || st.gPulse) {{\n      var g = (st.gCycle && st.gPulse) ? "@G" : st.gCycle ? "※G" : st.gPulse ? "*G" : "G:" + (st.gColor||"").slice(0,3);\n      parts.push(g);\n    }}\n    if(st.negative) parts.push("I");\n    if(st.fColor || st.fCycle || st.fPulse) {{\n      var f2 = (st.fCycle && st.fPulse) ? "@F" : st.fCycle ? "※F" : st.fPulse ? "*F" : "F:" + (st.fColor||"").slice(0,3);\n      parts.push(f2);\n    }}\n    return parts.join(" ") || "—";\n  }}\n\n  function applyState(st) {{\n    // stop all running effects first\n    stopAll();\n    // apply values\n    gColor   = st.gColor   || "";\n    gSize    = st.gSize    !== undefined ? st.gSize : 10;\n    fColor   = st.fColor   || "";\n    fOpacity = st.fOpacity !== undefined ? st.fOpacity : 40;\n    negative = !!st.negative;\n    document.getElementById("gSize").value    = gSize;\n    document.getElementById("fOpacity").value = fOpacity;\n    document.getElementById("gSizeVal").textContent = gSize;\n    document.getElementById("fOpVal").textContent   = fOpacity;\n    document.getElementById("iBtn").classList.toggle("active-i", negative);\n    updateSwatches("g"); updateSwatches("f");\n    // restart pulse/cycle if stored\n    if(st.gPulse) document.getElementById("gPulseBtn").click();\n    if(st.fPulse) document.getElementById("fPulseBtn").click();\n    if(st.gCycle) document.getElementById("gCycleBtn").click();\n    if(st.fCycle) document.getElementById("fCycleBtn").click();\n    updateAll();\n  }}\n\n  function savePresets() {{\n    localStorage.setItem(PRESETS_KEY, JSON.stringify(presets));\n  }}\n\n  function renderPresets() {{\n    var list = document.getElementById("presetList");\n    list.innerHTML = "";\n    document.getElementById("presetCount").textContent = presets.length ? presets.length : "";\n    if(presets.length === 0) {{\n      var empty = document.createElement("div");\n      empty.style.cssText = "padding:12px 10px;font-size:10px;color:#4a4a5a;text-align:center;";\n      empty.textContent = "no presets saved";\n      list.appendChild(empty);\n      return;\n    }}\n    presets.forEach(function(p, i) {{\n      var item = document.createElement("div");\n      item.className = "preset-item";\n\n      var load = document.createElement("button");\n      load.className = "preset-load";\n      load.innerHTML = p.name + \'<span class="preset-sub">\' + stateLabel(p.state) + \'</span>\';\n      load.onclick = function() {{ applyState(p.state); renderPresets(); }};\n\n      var del = document.createElement("button");\n      del.className = "preset-del";\n      del.textContent = "×";\n      del.title = "Delete";\n      del.onclick = function(e) {{\n        e.stopPropagation();\n        presets.splice(i, 1);\n        savePresets();\n        renderPresets();\n      }};\n\n      item.appendChild(load);\n      item.appendChild(del);\n      list.appendChild(item);\n    }});\n  }}\n\n  document.getElementById("presetSaveBtn").onclick = function() {{\n    var nameEl = document.getElementById("presetNameInput");\n    var name = nameEl.value.trim();\n    if(!name) {{ nameEl.focus(); return; }}\n    presets.push({{ name: name, state: getState() }});\n    savePresets();\n    nameEl.value = "";\n    renderPresets();\n  }};\n\n  document.getElementById("presetNameInput").addEventListener("keydown", function(e) {{\n    if(e.key === "Enter") document.getElementById("presetSaveBtn").click();\n  }});\n\n  /* ── PRESET TOGGLE ── */\n  var presetOpen   = false;\n  var presetToggleEl = document.getElementById("presetToggle");\n  var presetPanelEl  = document.getElementById("presetPanel");\n\n  function setPresetOpen(on) {{\n    presetOpen = on;\n    presetPanelEl.classList.toggle("open", presetOpen);\n    presetToggleEl.classList.toggle("active", presetOpen);\n    if(presetOpen) renderPresets();\n  }}\n\n  presetToggleEl.onclick = function() {{\n    setPresetOpen(!presetOpen);\n    if(presetOpen && sidebarOpen) setManifestOpen(false);\n  }};\n\n  renderPresets();\n\n\n  updateSwatches("g");\n  updateSwatches("f");\n  applyUrlEffects();\n\n}});\n</script>\n</body>\n</html>\n'
def process_folder(p,n):
    if not os.path.isfile(os.path.join(p,"manifest.json")): print(f"  SKIP  {n}"); return "skipped"
    g=next((f for f in sorted(os.listdir(p)) if f.lower().endswith(".gif") and not f.startswith("._")),None)
    if not g: print(f"  SKIP  {n}"); return "skipped"
    try:
        with open(os.path.join(p,"viewer.html"),"w",encoding="utf-8") as f: f.write(VIEWER_TEMPLATE.format(BASE=n,PLAYS_ONCE="false"))
        print(f"  OK    {n}"); return "ok"
    except Exception as e: print(f"  FAIL  {n}  ({e})"); return "failed"
def main():
    if not os.path.isdir(SYMBOLS_DIR): print("ERROR"); sys.exit(1)
    folders=sorted(f for f in os.listdir(SYMBOLS_DIR) if os.path.isdir(os.path.join(SYMBOLS_DIR,f)))
    counts={"ok":0,"skipped":0,"failed":0}
    for n in folders: counts[process_folder(os.path.join(SYMBOLS_DIR,n),n)]+=1
    print(f"Updated:{counts['ok']} Skipped:{counts['skipped']} Failed:{counts['failed']}")
if __name__=="__main__": main()
